+	.chan = LTC2378_PSEUDO_DIFF_CHANNEL(16),
+};
+
+static const struct ltc2378_chip_info ltc2368_18_chip_info = {
+	.name = "ltc2368-18",
+	.chan = LTC2378_PSEUDO_DIFF_CHANNEL(18),
+};
+
