 arch/powerpc/kernel/interrupt.c        | 32 +++++++++++++++-----------
 arch/powerpc/kernel/ptrace/ptrace.c    |  1 -
 arch/powerpc/kernel/signal.c           |  2 +-
 6 files changed, 26 insertions(+), 27 deletions(-)

